{
  "findings": [
    {
      "check_id": "CKV_AZURE_35",
      "title": "Storage account network access defaults to allow",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "HIGH",
      "explanation": "The default_action is set to \"Allow\", permitting storage account access from networks not explicitly listed in ip_rules. This makes the configured IP restriction ineffective."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\"]\n}\n",
  "fix_summary": "Changed the storage account network rules default action from Allow to Deny so access is restricted to explicitly permitted sources and configured bypass services."
}
